def is_prime(n):
    if n < 2:
        return False
    if n % 2 == 0:
        return n == 2
    d = 3
    while d * d <= n:
        if n % d == 0:
            return False
        d += 2
    return True

primes = []
n = 2

while len(primes) < 100:
    if is_prime(n):
        primes.append(n)
    n += 1

print("First 100 primes:", primes)
print("Count:", len(primes))
print("100th prime:", primes[-1])
print("Sum:", sum(primes))

